/**
 * gf.mjs — arithmetic in the Rijndael finite field GF(2^8).
 *
 * Everything the cipher needs that is "pure math" lives here: field
 * multiplication, the multiplicative inverse, the S-box pair derived from it,
 * and the round constants. All tables are *computed* at module load time from
 * the field definition rather than hard-coded, so the values cannot silently
 * disagree with the arithmetic used elsewhere.
 */

/** Reduction polynomial x^8 + x^4 + x^3 + x + 1 (0x11b), low 9 bits. */
const POLY = 0x11b;

/**
 * Multiply by x (i.e. by 0x02) in GF(2^8): shift left, reduce mod POLY.
 * @param {number} a byte
 * @returns {number} byte
 */
export function xtime(a) {
  const shifted = a << 1;
  return (shifted & 0x100) !== 0 ? (shifted ^ POLY) & 0xff : shifted & 0xff;
}

/**
 * Multiply two field elements (carry-less multiply, then reduce).
 * @param {number} a byte
 * @param {number} b byte
 * @returns {number} byte
 */
export function gmul(a, b) {
  let result = 0;
  let x = a & 0xff;
  let y = b & 0xff;
  while (y !== 0) {
    if ((y & 1) !== 0) result ^= x;
    x = xtime(x);
    y >>= 1;
  }
  return result & 0xff;
}

/**
 * Multiplicative inverse in GF(2^8); 0 maps to 0 by convention (as in AES).
 * Found by exhaustive search, which is trivially cheap for 256 elements and
 * avoids depending on a log/antilog table being correct.
 * @param {number} a byte
 * @returns {number} byte
 */
function inverse(a) {
  if (a === 0) return 0;
  for (let candidate = 1; candidate < 256; candidate++) {
    if (gmul(a, candidate) === 1) return candidate;
  }
  /* c8 ignore next */
  throw new Error('no inverse in GF(2^8) — unreachable for a non-zero byte');
}

/** Rotate a byte left by `n` bits (8-bit circular shift). */
function rotl8(value, n) {
  return ((value << n) | (value >>> (8 - n))) & 0xff;
}

/**
 * The AES S-box: multiplicative inverse followed by the fixed affine
 * transform b ^ rotl(b,1) ^ rotl(b,2) ^ rotl(b,3) ^ rotl(b,4) ^ 0x63.
 */
export const SBOX = new Uint8Array(256);
/** The inverse S-box, obtained by inverting the permutation above. */
export const INV_SBOX = new Uint8Array(256);

for (let i = 0; i < 256; i++) {
  const b = inverse(i);
  const s = (b ^ rotl8(b, 1) ^ rotl8(b, 2) ^ rotl8(b, 3) ^ rotl8(b, 4) ^ 0x63) & 0xff;
  SBOX[i] = s;
  INV_SBOX[s] = i;
}

// Cheap self-check on the two anchor values of the published S-box. If the
// field arithmetic above were wrong, the cipher would fail in ways that are
// much harder to localise than this assertion.
if (SBOX[0x00] !== 0x63 || SBOX[0x01] !== 0x7c || SBOX[0x53] !== 0xed) {
  /* c8 ignore next */
  throw new Error('S-box construction failed: GF(2^8) arithmetic is broken');
}

/**
 * Round constants Rcon[i] = x^(i-1) in GF(2^8), used by key expansion.
 * Index 0 is unused/padding; 10 entries are enough for AES-128 (the widest
 * consumer of Rcon, since larger keys need fewer iterations).
 */
export const RCON = new Uint8Array(11);
RCON[0] = 0x8d; // never read; matches the conventional table
let rc = 1;
for (let i = 1; i <= 10; i++) {
  RCON[i] = rc;
  rc = xtime(rc);
}

