/**
 * aes-core.mjs — the raw Rijndael block cipher (FIPS-197), 128/192/256-bit
 * keys, single 16-byte block in / 16-byte block out. No modes, no padding,
 * no I/O: those belong to the layers above.
 *
 * State convention: a block is a flat 16-byte array in column-major order,
 * exactly as it arrives on the wire. Byte index `4*c + r` is row `r` of
 * column `c`, which is what ShiftRows/MixColumns are defined against.
 */

import { SBOX, INV_SBOX, RCON, gmul } from './gf.mjs';

/** AES block size in bytes. */
export const BLOCK_SIZE = 16;

/** Key sizes accepted by AES, in bytes. */
const VALID_KEY_SIZES = new Set([16, 24, 32]);

/**
 * @param {Uint8Array} key
 * @returns {boolean} whether `key` has a length AES can use
 */
export function isValidKeySize(key) {
  return VALID_KEY_SIZES.has(key.length);
}

/**
 * Expand a cipher key into `4 * (rounds + 1)` 32-bit words, flattened to
 * bytes so that round key `n` is the 16-byte slice starting at `16 * n`.
 *
 * @param {Uint8Array} key 16, 24 or 32 bytes
 * @returns {{ roundKeys: Uint8Array, rounds: number }}
 */
export function expandKey(key) {
  const nk = key.length / 4; // key length in 32-bit words: 4, 6 or 8
  const rounds = nk + 6; // 10, 12 or 14
  const totalWords = 4 * (rounds + 1);
  const roundKeys = new Uint8Array(totalWords * 4);

  roundKeys.set(key, 0);

  for (let i = nk; i < totalWords; i++) {
    const p = (i - 1) * 4; // previous word
    let t0 = roundKeys[p];
    let t1 = roundKeys[p + 1];
    let t2 = roundKeys[p + 2];
    let t3 = roundKeys[p + 3];

    if (i % nk === 0) {
      // RotWord, then SubWord, then xor the round constant into the first byte.
      const rotated = [t1, t2, t3, t0];
      t0 = SBOX[rotated[0]] ^ RCON[i / nk];
      t1 = SBOX[rotated[1]];
      t2 = SBOX[rotated[2]];
      t3 = SBOX[rotated[3]];
    } else if (nk > 6 && i % nk === 4) {
      // Extra SubWord for 256-bit keys only.
      t0 = SBOX[t0];
      t1 = SBOX[t1];
      t2 = SBOX[t2];
      t3 = SBOX[t3];
    }

    const q = (i - nk) * 4; // word `nk` positions back
    const o = i * 4;
    roundKeys[o] = roundKeys[q] ^ t0;
    roundKeys[o + 1] = roundKeys[q + 1] ^ t1;
    roundKeys[o + 2] = roundKeys[q + 2] ^ t2;
    roundKeys[o + 3] = roundKeys[q + 3] ^ t3;
  }

  return { roundKeys, rounds };
}

/** state ^= roundKeys[round] */
function addRoundKey(state, roundKeys, round) {
  const base = round * BLOCK_SIZE;
  for (let i = 0; i < BLOCK_SIZE; i++) state[i] ^= roundKeys[base + i];
}

/** Substitute every byte through `box` (SBOX or INV_SBOX). */
function subBytes(state, box) {
  for (let i = 0; i < BLOCK_SIZE; i++) state[i] = box[state[i]];
}

/**
 * Rotate row `r` left by `r` positions (forward) or right by `r` (inverse).
 * @param {Uint8Array} state
 * @param {boolean} inverse
 */
function shiftRows(state, inverse) {
  const copy = state.slice();
  for (let r = 1; r < 4; r++) {
    for (let c = 0; c < 4; c++) {
      const from = inverse ? (c - r + 4) % 4 : (c + r) % 4;
      state[4 * c + r] = copy[4 * from + r];
    }
  }
}

/**
 * Mix each column by the fixed MDS matrix (or its inverse).
 * Forward coefficients are {2,3,1,1}; inverse are {14,11,13,9}.
 * @param {Uint8Array} state
 * @param {boolean} inverse
 */
function mixColumns(state, inverse) {
  const [m0, m1, m2, m3] = inverse ? [14, 11, 13, 9] : [2, 3, 1, 1];
  for (let c = 0; c < 4; c++) {
    const o = 4 * c;
    const a0 = state[o];
    const a1 = state[o + 1];
    const a2 = state[o + 2];
    const a3 = state[o + 3];
    state[o] = gmul(a0, m0) ^ gmul(a1, m1) ^ gmul(a2, m2) ^ gmul(a3, m3);
    state[o + 1] = gmul(a0, m3) ^ gmul(a1, m0) ^ gmul(a2, m1) ^ gmul(a3, m2);
    state[o + 2] = gmul(a0, m2) ^ gmul(a1, m3) ^ gmul(a2, m0) ^ gmul(a3, m1);
    state[o + 3] = gmul(a0, m1) ^ gmul(a1, m2) ^ gmul(a2, m3) ^ gmul(a3, m0);
  }
}

/**
 * The AES block cipher bound to one expanded key.
 *
 * Instances are reusable and stateless between calls, which is what makes an
 * ECB "mode of operation" object safe to call repeatedly.
 */
export class AES {
  /**
   * @param {Uint8Array} key 16, 24 or 32 bytes (validated by the caller)
   */
  constructor(key) {
    const { roundKeys, rounds } = expandKey(key);
    this.roundKeys = roundKeys;
    this.rounds = rounds;
  }

  /**
   * Encrypt exactly one block.
   * @param {Uint8Array} block 16 bytes
   * @returns {Uint8Array} 16 bytes
   */
  encryptBlock(block) {
    const state = Uint8Array.from(block);

    addRoundKey(state, this.roundKeys, 0);
    for (let round = 1; round < this.rounds; round++) {
      subBytes(state, SBOX);
      shiftRows(state, false);
      mixColumns(state, false);
      addRoundKey(state, this.roundKeys, round);
    }
    // Final round omits MixColumns.
    subBytes(state, SBOX);
    shiftRows(state, false);
    addRoundKey(state, this.roundKeys, this.rounds);

    return state;
  }

  /**
   * Decrypt exactly one block (straightforward inverse cipher).
   * @param {Uint8Array} block 16 bytes
   * @returns {Uint8Array} 16 bytes
   */
  decryptBlock(block) {
    const state = Uint8Array.from(block);

    addRoundKey(state, this.roundKeys, this.rounds);
    for (let round = this.rounds - 1; round > 0; round--) {
      shiftRows(state, true);
      subBytes(state, INV_SBOX);
      addRoundKey(state, this.roundKeys, round);
      mixColumns(state, true);
    }
    shiftRows(state, true);
    subBytes(state, INV_SBOX);
    addRoundKey(state, this.roundKeys, 0);

    return state;
  }
}

