/**
 * pybytes.mjs — the parts of CPython's `bytes` behaviour this program relies
 * on: UTF-8 encoding of a `str` and the exact `repr()` that `print()` uses
 * when handed a bytes object.
 */

const encoder = new TextEncoder();

/**
 * Equivalent of Python's `str.encode()` (UTF-8, no BOM).
 * @param {string} text
 * @returns {Uint8Array}
 */
export function encodeUtf8(text) {
  return encoder.encode(text);
}

/**
 * Reproduce CPython's `bytes.__repr__`.
 *
 * The rules, in the order CPython applies them:
 *   - the quote is `'` unless the data contains `'` but no `"`, in which case
 *     it is `"` (so the quote never needs escaping in that case);
 *   - backslash and the active quote are backslash-escaped;
 *   - \t, \n and \r get their short escapes;
 *   - anything below 0x20 or at/above 0x7f becomes \xNN with lowercase hex;
 *   - every other byte is emitted as its ASCII character.
 *
 * @param {Uint8Array} bytes
 * @returns {string} e.g. `b"\x02}\xa7'4B"`
 */
export function bytesRepr(bytes) {
  const hasSingle = bytes.includes(0x27);
  const hasDouble = bytes.includes(0x22);
  const quote = hasSingle && !hasDouble ? '"' : "'";
  const quoteByte = quote.charCodeAt(0);

  let out = 'b' + quote;
  for (const byte of bytes) {
    if (byte === quoteByte || byte === 0x5c /* \ */) {
      out += '\\' + String.fromCharCode(byte);
    } else if (byte === 0x09) {
      out += '\\t';
    } else if (byte === 0x0a) {
      out += '\\n';
    } else if (byte === 0x0d) {
      out += '\\r';
    } else if (byte < 0x20 || byte >= 0x7f) {
      out += '\\x' + byte.toString(16).padStart(2, '0');
    } else {
      out += String.fromCharCode(byte);
    }
  }
  return out + quote;
}

