    if (!isValidKeySize(key)) throw new PyValueError('Invalid key size');
    this.name = MODE_NAME;
    this.blockSize = BLOCK_SIZE;
    this._aes = new AES(key);
  }

  /**
   * @param {Uint8Array} plaintext exactly 16 bytes
   * @returns {Uint8Array} 16 bytes of ciphertext
   * @throws {PyValueError} if the block is the wrong size
   */
  encrypt(plaintext) {
    if (plaintext.length !== BLOCK_SIZE) {
      throw new PyValueError('plaintext block must be 16 bytes');
    }
    return this._aes.encryptBlock(plaintext);
  }

