 * a bad key/block length raises ValueError with a Python traceback and exit 1.
 */

import { ArgumentParser } from './lib/argparse.mjs';
import * as pyaes from './lib/pyaes.mjs';
import { bytesRepr, encodeUtf8 } from './lib/pybytes.mjs';
import { PyValueError, dieWithTraceback } from './lib/pyerrors.mjs';

/**
 * The reference program is a PyInstaller bundle, so argparse sees
 * `sys.argv[0] == '.../test15_executable'` and the bootloader names the
 * script `test15`. Both strings are pinned here so usage, error and traceback
 * output is byte-identical to the binary being matched.
 */
const PROG = 'test15_executable';
const SCRIPT = 'test15';

/** `print(value)` — str() of a bytes object is its repr. */
function printBytes(bytes) {
  process.stdout.write(bytesRepr(bytes) + '\n');
}

/**
 * Underline `expression` inside `source` the way CPython 3.11+ does.
 * @param {string} source
 * @param {string} expression
 * @returns {string}
 */
function caretFor(source, expression) {
  const column = source.indexOf(expression);
  return ' '.repeat(column) + '^'.repeat(expression.length);
}

/** One entry per statement in main() that can raise, with its Python frames. */
function frames(line, source, expression, innerFrames) {
  return [
    { file: 'test15.py', line: 20, name: '<module>', source: 'main()' },
    {
      file: 'test15.py',
      line,
      name: 'main',
      source,
      caret: caretFor(source, expression),
    },
    ...innerFrames,
  ];
}

/** Frames inside pyaes for a rejected key (AESModeOfOperationECB.__init__). */
const KEY_FRAMES = [
  { file: 'pyaes/aes.py', line: 304, name: '__init__' },
  { file: 'pyaes/aes.py', line: 134, name: '__init__' },
];

const CALL_SITES = {
  key1: frames(
    12,
    'aes1 = pyaes.AESModeOfOperationECB(args.key1.encode())  # Initialize first AES ECB cipher',
    'pyaes.AESModeOfOperationECB(args.key1.encode())',
    KEY_FRAMES
  ),
  key2: frames(
    13,
    'aes2 = pyaes.AESModeOfOperationECB(args.key2.encode())  # Initialize second AES ECB cipher',
    'pyaes.AESModeOfOperationECB(args.key2.encode())',
    KEY_FRAMES
  ),
  encrypt: frames(
    14,
    'ciphertext = aes1.encrypt(args.data.encode())  # Encrypt with first key',
    'aes1.encrypt(args.data.encode())',
