/**
 * pyerrors.mjs — Python-shaped exceptions and the interpreter's exit
 * behaviour for an uncaught one.
 *
 * The reference build is a PyInstaller bundle of test15.py: an uncaught
 * ValueError prints a traceback on stderr and exits 1, leaving stdout empty.
 *
 * One subtlety worth spelling out, because it is easy to mistake for a bug:
 * the frozen bundle carries no source files, so a traceback frame only shows
 * its source line when CPython's `linecache` happens to find the named file
 * *relative to the current working directory*. Running the reference binary
 * from the directory holding test15.py prints the source lines and carets;
 * running it from anywhere else prints bare `File "...", line N` frames. The
 * lookup below reproduces that, reading whatever is on disk rather than
 * assuming the source is there.
 */

import { readFileSync } from 'node:fs';

/** Mirror of Python's built-in ValueError. */
export class PyValueError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValueError';
    this.pyType = 'ValueError';
  }
}

/**
 * A traceback frame.
 * @typedef {object} PyFrame
 * @property {string} file  path as it appears in `File "..."`, resolved
 *                          relative to cwd when looking for source
 * @property {number} line  line number within that file
 * @property {string} name  enclosing scope, e.g. `main` or `<module>`
 * @property {string} [expression] sub-expression that raised; underlined with
 *                          carets when the source line is available and the
 *                          expression is narrower than the whole line
 */

/**
 * Stand-in for `linecache.getline()`: read one line of `file` relative to the
 * process's cwd, stripped as `traceback` strips it. Returns '' when the file
 * or the line is unavailable, which is also `traceback`'s signal to print no
 * source at all.
 *
 * @param {string} file
 * @param {number} lineno 1-based
 * @returns {string}
 */
function getSourceLine(file, lineno) {
  let text;
  try {
    text = readFileSync(file, 'utf8');
  } catch {
    return '';
  }
  const lines = text.split('\n');
  return lineno >= 1 && lineno <= lines.length ? lines[lineno - 1].trim() : '';
}

/**
 * Render a traceback the way CPython 3.11+ formats one.
 * @param {PyFrame[]} frames outermost frame first
 * @param {Error} error
 * @returns {string} ends with a newline
 */
export function formatTraceback(frames, error) {
  const lines = ['Traceback (most recent call last):'];

  for (const frame of frames) {
    lines.push(`  File "${frame.file}", line ${frame.line}, in ${frame.name}`);

    const source = getSourceLine(frame.file, frame.line);
    if (source === '') continue;
    lines.push(`    ${source}`);

    // Carets are drawn only when the failing expression is a proper subset of
    // the line; CPython suppresses them when they would span everything. If
    // the file on disk is not the source this program was built from, the
    // expression will not be found and the anchors are skipped (CPython would
    // draw approximate `~^~` anchors from stored column offsets there).
    const expression = frame.expression;
    if (expression === undefined || expression === source) continue;
    const column = source.indexOf(expression);
    if (column === -1) continue;
    lines.push(`    ${' '.repeat(column)}${'^'.repeat(expression.length)}`);
  }

  const type = error instanceof PyValueError ? error.pyType : 'Exception';
  lines.push(`${type}: ${error.message}`);
  return lines.join('\n') + '\n';
}

/**
 * Print the traceback plus PyInstaller's bootloader notice and exit 1, the
 * way the packaged reference program dies.
 * @param {PyFrame[]} frames
 * @param {Error} error
 * @param {string} script script name reported by the bootloader
 * @returns {never}
 */
export function dieWithTraceback(frames, error, script) {
  process.stderr.write(formatTraceback(frames, error));
  process.stderr.write(
    `[PYI-${process.pid}:ERROR] Failed to execute script '${script}' due to unhandled exception!\n`
  );
  process.exit(1);
}

