/**
 * test15.mjs — Node.js port of /workspace/dataset/test15.py.
 *
 * Encrypts one 16-byte block under `--key1`, then "decrypts" that ciphertext
 * under the unrelated `--key2`, and prints both results as Python bytes
 * literals. Run it exactly like the reference build:
 *
 *   node test15.mjs --key1 KEY1 --key2 KEY2 --data DATA
 *
 * Failure modes are matched too: argparse errors go to stderr with exit 2, and
 * a bad key/block length raises ValueError with a Python traceback and exit 1.
 */

import { ArgumentParser } from './lib/argparse.mjs';
import * as pyaes from './lib/pyaes.mjs';
import { bytesRepr, encodeUtf8 } from './lib/pybytes.mjs';
import { PyValueError, dieWithTraceback } from './lib/pyerrors.mjs';

/**
 * The reference program is a PyInstaller bundle, so argparse sees
 * `sys.argv[0] == '.../test15_executable'` and the bootloader names the
 * script `test15`. Both strings are pinned here so usage, error and traceback
 * output is byte-identical to the binary being matched.
 */
const PROG = 'test15_executable';
const SCRIPT = 'test15';

/** `print(value)` — str() of a bytes object is its repr. */
function printBytes(bytes) {
  process.stdout.write(bytesRepr(bytes) + '\n');
}

/**
 * Traceback frames for each statement in main() that can raise, mirroring the
 * line numbers and call expressions of test15.py. The `expression` fields are
 * what CPython underlines with carets; the source text itself is read from
 * disk at print time (see pyerrors.mjs).
 */
function pythonFrames(line, expression, insideLibrary) {
  return [
    { file: 'test15.py', line: 20, name: '<module>', expression: 'main()' },
    { file: 'test15.py', line, name: 'main', expression },
    ...insideLibrary,
  ];
}

/** Frames inside pyaes for a rejected key (AESModeOfOperationECB.__init__). */
const KEY_FRAMES = [
  { file: 'pyaes/aes.py', line: 304, name: '__init__' },
  { file: 'pyaes/aes.py', line: 134, name: '__init__' },
];

const CALL_SITES = {
  key1: pythonFrames(12, 'pyaes.AESModeOfOperationECB(args.key1.encode())', KEY_FRAMES),
  key2: pythonFrames(13, 'pyaes.AESModeOfOperationECB(args.key2.encode())', KEY_FRAMES),
  encrypt: pythonFrames(14, 'aes1.encrypt(args.data.encode())', [
    { file: 'pyaes/aes.py', line: 342, name: 'encrypt' },
  ]),
  // Unreachable here — the ciphertext handed to decrypt() always comes from
  // encrypt() and is therefore exactly one block. Wired up for completeness;
  // its pyaes line number is the one thing below that the reference binary
  // never gets a chance to reveal.
  decrypt: pythonFrames(15, 'aes2.decrypt(ciphertext)', [
    { file: 'pyaes/aes.py', line: 350, name: 'decrypt' },
  ]),
};

/**
 * Run `body`; if it raises a Python ValueError, die like the interpreter does
 * at the given call site.
 * @template T
 * @param {keyof typeof CALL_SITES} site
 * @param {() => T} body
 * @returns {T}
 */
function atCallSite(site, body) {
  try {
    return body();
  } catch (error) {
    if (error instanceof PyValueError) dieWithTraceback(CALL_SITES[site], error, SCRIPT);
    throw error;
  }
}

function main() {
  const parser = new ArgumentParser({ prog: PROG });
  parser.addArgument(['--key1'], { required: true }); // First 16 bytes key
  parser.addArgument(['--key2'], { required: true }); // Second 16 bytes key
  parser.addArgument(['--data'], { required: true }); // 16 bytes data
  const args = parser.parseArgs(process.argv.slice(2));

  // Encrypt with first key, decrypt with second key
  const aes1 = atCallSite('key1', () => new pyaes.AESModeOfOperationECB(encodeUtf8(args.key1)));
  const aes2 = atCallSite('key2', () => new pyaes.AESModeOfOperationECB(encodeUtf8(args.key2)));
  const ciphertext = atCallSite('encrypt', () => aes1.encrypt(encodeUtf8(args.data)));
  const wrongPlaintext = atCallSite('decrypt', () => aes2.decrypt(ciphertext));
  printBytes(ciphertext);
  printBytes(wrongPlaintext);
}

main();

