const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

/** Indentation constants from argparse's HelpFormatter. */
const INDENT = 2;
const MAX_HELP_POSITION = 24;

export class ArgumentParser {
  /**
   * @param {{ prog: string }} options `prog` is the name shown in usage and
   *   error lines (argparse defaults it to basename(sys.argv[0])).
   */
  constructor({ prog }) {
    this.prog = prog;
    /** @type {Array<{optionStrings: string[], dest: string, metavar: string|null, nargs: number, required: boolean, help: string|null}>} */
    this.actions = [];
    this.addArgument(['-h', '--help'], {
      nargs: 0,
      help: 'show this help message and exit',
    });
  }

  /**
   * Declare an option. Mirrors `add_argument` for the flags used here; `type`
   * is intentionally absent because every value in this program stays a str.
   *
   * @param {string[]} optionStrings e.g. `['--key1']`
   * @param {{ required?: boolean, nargs?: number, help?: string|null, metavar?: string|null }} [config]
   */
  addArgument(optionStrings, config = {}) {
    const longest = optionStrings.find((s) => s.startsWith('--')) ?? optionStrings[0];
    const dest = longest.replace(/^-+/, '').replace(/-/g, '_');
    const nargs = config.nargs ?? 1;
    this.actions.push({
      optionStrings,
      dest,
      metavar: config.metavar ?? (nargs === 0 ? null : dest.toUpperCase()),
      nargs,
      required: config.required ?? false,
      help: config.help ?? null,
    });
  }

  /** `'--key1 KEY1'` — how an action appears in usage and help. */
  _formatInvocation(action, optionString) {
    if (action.nargs === 0) return optionString;
    return `${optionString} ${action.metavar}`;
  }

  /** The `usage: ...` line, without a trailing newline. */
  formatUsage() {
    const parts = this.actions.map((action) => {
      const body = this._formatInvocation(action, action.optionStrings[0]);
      return action.required ? body : `[${body}]`;
    });
    return `usage: ${[this.prog, ...parts].join(' ')}`;
  }

  /** Full `-h` output, ending in a newline. */
  formatHelp() {
    // argparse aligns help text at `help_position`, derived from the longest
    // invocation across all actions (capped at MAX_HELP_POSITION).
    const invocations = this.actions.map((a) =>
      a.optionStrings.map((s) => this._formatInvocation(a, s)).join(', ')
    );
    const actionMaxLength = Math.max(...invocations.map((i) => i.length)) + INDENT;
    const helpPosition = Math.min(actionMaxLength + 2, MAX_HELP_POSITION);
    const actionWidth = helpPosition - INDENT - 2;

    const lines = [this.formatUsage(), '', 'options:'];
    this.actions.forEach((action, index) => {
      const header = invocations[index];
      if (action.help) {
        lines.push(`${' '.repeat(INDENT)}${header.padEnd(actionWidth)}  ${action.help}`);
      } else {
        lines.push(`${' '.repeat(INDENT)}${header}`);
      }
    });
    return lines.join('\n') + '\n';
  }

  /** Print help on stdout and exit 0, like argparse's help action. */
  printHelpAndExit() {
    process.stdout.write(this.formatHelp());
    process.exit(0);
  }

  /**
   * `parser.error(message)`: usage plus one error line on stderr, exit 2.
   * @param {string} message
   * @returns {never}
   */
  error(message) {
    process.stderr.write(this.formatUsage() + '\n');
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  /** All option strings, in declaration order — the lookup argparse builds. */
  _optionStringActions() {
    /** @type {Map<string, object>} */
    const map = new Map();
    for (const action of this.actions) {
      for (const optionString of action.optionStrings) map.set(optionString, action);
    }
    return map;
  }

  /**
   * Classify one token the way argparse's `_parse_optional` does.
   *
   * @param {string} token
   * @returns {{kind: 'value'|'unknown'|'doubleDash'} | {kind: 'option', action: object, optionString: string, explicitValue: string|null}}
   */
  _classify(token) {
    if (token === '' || !token.startsWith('-')) return { kind: 'value' };
    // `--` is recognised before any option matching, so it never resolves as
    // an abbreviation and never serves as a value.
    if (token === '--') return { kind: 'doubleDash' };

    const options = this._optionStringActions();
    if (options.has(token)) {
      return { kind: 'option', action: options.get(token), optionString: token, explicitValue: null };
    }
    if (token.length === 1) return { kind: 'value' }; // a lone '-'

    const eq = token.indexOf('=');
    if (eq !== -1) {
      const prefix = token.slice(0, eq);
      if (options.has(prefix)) {
        return {
          kind: 'option',
          action: options.get(prefix),
          optionString: prefix,
          explicitValue: token.slice(eq + 1),
        };
      }
    }

    // Abbreviation: match on the part before '=' if there is one.
    const [head, ...rest] = eq === -1 ? [token] : [token.slice(0, eq), token.slice(eq + 1)];
    const matches = [...options.entries()].filter(([optionString]) => optionString.startsWith(head));
    if (matches.length > 1) {
      const candidates = matches.map(([optionString]) => optionString).join(', ');
      this.error(`ambiguous option: ${token} could match ${candidates}`);
    }
    if (matches.length === 1) {
      const [optionString, action] = matches[0];
      return {
        kind: 'option',
        action,
        optionString,
        explicitValue: rest.length > 0 ? rest[0] : null,
      };
    }

    // argparse lets these through as values rather than option-like tokens.
    if (NEGATIVE_NUMBER.test(token)) return { kind: 'value' };
    if (token.includes(' ')) return { kind: 'value' };

    return { kind: 'unknown' };
  }

  /** First option string of an action — argparse's `_get_action_name`. */
  _actionName(action) {
    return action.optionStrings.join('/');
  }

  /**
   * Parse argument tokens (i.e. `process.argv.slice(2)`).
   * Exits the process on `-h`, a parse error, or a missing required option.
   *
   * @param {string[]} argv
   * @returns {Record<string, string|null>} namespace keyed by dest
   */
  parseArgs(argv) {
    /** @type {Record<string, string|null>} */
    const namespace = {};
    for (const action of this.actions) {
      if (action.nargs !== 0) namespace[action.dest] = null;
    }

    const extras = [];
    const seen = new Set();
    let optionsEnded = false;

    for (let i = 0; i < argv.length; i++) {
      const token = argv[i];

      if (!optionsEnded && token === '--') {
        optionsEnded = true; // only the first '--' is consumed
        continue;
      }
      if (optionsEnded) {
        extras.push(token);
        continue;
      }

      const parsed = this._classify(token);
      if (parsed.kind === 'value' || parsed.kind === 'unknown') {
        extras.push(token);
        continue;
      }

      const { action, optionString, explicitValue } = parsed;

      if (action.nargs === 0) {
        if (explicitValue !== null) {
          this.error(`argument ${this._actionName(action)}: ignored explicit argument '${explicitValue}'`);
        }
        if (action.dest === 'help') this.printHelpAndExit();
        seen.add(action.dest);
        continue;
      }

      let value = explicitValue;
      if (value === null) {
        const next = i + 1 < argv.length ? argv[i + 1] : null;
        if (next === null || this._classify(next).kind !== 'value') {
          this.error(`argument ${this._actionName(action)}: expected one argument`);
        }
        value = next;
        i++;
      }
      namespace[action.dest] = value; // a repeated option simply overwrites
      seen.add(action.dest);
    }

    // Required options are checked before unrecognised extras, matching the
    // order in which parse_args/parse_known_args report problems.
    const missing = this.actions
      .filter((action) => action.required && !seen.has(action.dest))
      .map((action) => this._actionName(action));
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    return namespace;
  }
}

/**
 * difftest.mjs — differential harness: runs the same argv through the
 * reference binary and the JS port and compares stdout, stderr and exit code.
 * Not part of the deliverable; lives here for verification only.
 */
import { spawnSync } from 'node:child_process';

const REF = '/workspace/dataset/test15_executable';
const JS = ['/output/test15.mjs'];

// The bootloader stamps its PID into the crash notice, so that one line can
// never match; everything above it must.
const stripPid = (text) => text.replace(/\[PYI-\d+:ERROR\]/g, '[PYI-PID:ERROR]');

function run(cmd, args, argv) {
  const r = spawnSync(cmd, [...args, ...argv], { encoding: 'buffer' });
  return {
    stdout: r.stdout.toString('binary'),
    stderr: stripPid(r.stderr.toString('binary')),
    code: r.status,
  };
}

let pass = 0;
const failures = [];

function check(label, argv) {
  const ref = run(REF, [], argv);
  const js = run('node', JS, argv);
  const same = ref.stdout === js.stdout && ref.stderr === js.stderr && ref.code === js.code;
  if (same) pass++;
  else failures.push({ label, argv, ref, js });
  return same;
}

const rand = (n, lo = 32, hi = 126) =>
  Array.from({ length: n }, () => String.fromCharCode(lo + Math.floor(Math.random() * (hi - lo + 1)))).join('');

const cases = [];

// Random keys/data at every legal key size, plus mismatched sizes.
for (let i = 0; i < 60; i++) cases.push(['aes128', ['--key1', rand(16), '--key2', rand(16), '--data', rand(16)]]);
for (let i = 0; i < 10; i++) cases.push(['aes192', ['--key1', rand(24), '--key2', rand(24), '--data', rand(16)]]);
for (let i = 0; i < 10; i++) cases.push(['aes256', ['--key1', rand(32), '--key2', rand(32), '--data', rand(16)]]);
for (let i = 0; i < 6; i++) cases.push(['mixed-sizes', ['--key1', rand(16), '--key2', rand(32), '--data', rand(16)]]);
for (let i = 0; i < 6; i++) cases.push(['k1-192-k2-256', ['--key1', rand(24), '--key2', rand(32), '--data', rand(16)]]);

// Byte values that stress bytes-repr: high bytes, control chars, quotes.
for (let i = 0; i < 12; i++) cases.push(['low-ascii', ['--key1', rand(16, 32, 47), '--key2', rand(16, 32, 47), '--data', rand(16, 32, 47)]]);
cases.push(['quotes', ['--key1', '\'"\'"\'"\'"\'"\'"\'"\'"', '--key2', '""""""""\'\'\'\'\'\'\'\'', '--data', '\\\\\\\\\'\'\'\'""""\t\n\r\x0b']]);
cases.push(['tabs-newlines', ['--key1', 'a\tb\nc\rd\\efghijk', '--key2', '\t\t\t\t\n\n\n\n\r\r\r\r\\\\\\\\', '--data', '\t\n\r\\"\'abcdefghi']]);
cases.push(['identity-roundtrip', ['--key1', '0123456789abcdef', '--key2', '0123456789abcdef', '--data', '0123456789abcdef']]);
cases.push(['all-same-char', ['--key1', 'AAAAAAAAAAAAAAAA', '--key2', 'AAAAAAAAAAAAAAAA', '--data', 'AAAAAAAAAAAAAAAA']]);

// Multi-byte UTF-8: encode() decides the byte length, not the char count.
cases.push(['utf8-16-bytes', ['--key1', 'éeeeeeeeeeeeeee', '--key2', '0123456789abcdef', '--data', 'ééeeeeeeeeeeee']]);
cases.push(['utf8-emoji', ['--key1', '😀😀😀😀', '--key2', '😀😀😀😀', '--data', '😀😀😀😀']]);
cases.push(['utf8-cjk', ['--key1', '中文密钥测试abcd', '--key2', '0123456789abcdef', '--data', '中文数据中文abcd']]);
cases.push(['utf8-too-long', ['--key1', 'ééééééééééééééé', '--key2', '0123456789abcdef', '--data', '0123456789abcdef']]);

// Wrong lengths -> ValueError paths.
for (const n of [0, 1, 15, 17, 23, 25, 31, 33, 48]) {
  cases.push([`key1-len-${n}`, ['--key1', rand(n), '--key2', rand(16), '--data', rand(16)]]);
  cases.push([`key2-len-${n}`, ['--key1', rand(16), '--key2', rand(n), '--data', rand(16)]]);
  cases.push([`data-len-${n}`, ['--key1', rand(16), '--key2', rand(16), '--data', rand(n)]]);
}

// argparse surface.
const K = '0123456789abcdef';
cases.push(['no-args', []]);
cases.push(['help', ['-h']]);
cases.push(['help-long', ['--help']]);
cases.push(['help-with-others', ['--key1', K, '-h']]);
cases.push(['missing-data', ['--key1', K, '--key2', K]]);
cases.push(['missing-key2-data', ['--key1', K]]);
cases.push(['equals-form', [`--key1=${K}`, `--key2=${K}`, `--data=${K}`]]);
cases.push(['abbrev', ['--key1', K, '--key2', K, '--dat', K]]);
cases.push(['abbrev-min', ['--key1', K, '--key2', K, '--d', K]]);
cases.push(['abbrev-equals', [`--key1=${K}`, `--key2=${K}`, `--da=${K}`]]);
cases.push(['ambiguous-key', ['--key', K, '--key2', K, '--data', K]]);
cases.push(['ambiguous-k', ['--k', K, '--key2', K, '--data', K]]);
cases.push(['ambiguous-equals', [`--key=${K}`, '--key2', K, '--data', K]]);
cases.push(['unknown-opt', ['--key1', K, '--key2', K, '--data', K, '--foo', '1']]);
cases.push(['unknown-opt-only', ['--foo']]);
cases.push(['positional-extra', ['--key1', K, '--key2', K, '--data', K, 'extra']]);
cases.push(['dash-dash', ['--', '--key1', K, '--key2', K, '--data', K]]);
cases.push(['dash-dash-after', ['--key1', K, '--key2', K, '--data', K, '--']]);
cases.push(['dash-value', ['--key1', '-123456789abcdef', '--key2', K, '--data', K]]);
cases.push(['negative-number-value', ['--key1', K, '--key2', K, '--data', '-5']]);
cases.push(['negative-float-value', ['--key1', K, '--key2', K, '--data', '-5.5']]);
cases.push(['negative-number-equals', ['--key1', K, '--key2', K, `--data=-5`]]);
cases.push(['value-with-space-dash', ['--key1', K, '--key2', K, '--data', '-a bcdefghijklmn']]);
cases.push(['lone-dash-value', ['--key1', '-', '--key2', K, '--data', K]]);
cases.push(['empty-value', ['--key1', '', '--key2', K, '--data', K]]);
cases.push(['empty-equals', ['--key1=', '--key2', K, '--data', K]]);
cases.push(['missing-value-at-end', ['--key1', K, '--key2', K, '--data']]);
cases.push(['duplicate-last-wins', ['--key1', 'ffffffffffffffff', '--key1', K, '--key2', K, '--data', K]]);
cases.push(['duplicate-data', ['--key1', K, '--key2', K, '--data', 'AAAAAAAAAAAAAAAA', '--data', K]]);
cases.push(['out-of-order', ['--data', K, '--key2', K, '--key1', K]]);
cases.push(['equals-inside-value', ['--key1', `a=b456789abcdef1`, '--key2', K, '--data', K]]);
cases.push(['help-abbrev', ['--hel']]);
cases.push(['double-dash-only-first', ['--', '--', '--key1', K]]);

for (const [label, argv] of cases) check(label, argv);

console.log(`pass ${pass}/${cases.length}`);
for (const f of failures.slice(0, 12)) {
  console.log(`\nFAIL [${f.label}] argv=${JSON.stringify(f.argv)}`);
  console.log(`  ref: code=${f.ref.code} out=${JSON.stringify(f.ref.stdout)} err=${JSON.stringify(f.ref.stderr)}`);
  console.log(`  js : code=${f.js.code} out=${JSON.stringify(f.js.stdout)} err=${JSON.stringify(f.js.stderr)}`);
}
process.exit(failures.length === 0 ? 0 : 1);

