/**
 * corecheck.mjs — two independent checks of the port:
 *   1. the raw cipher against the published FIPS-197 / SP 800-38A vectors
 *      (keys with non-UTF-8 bytes, so the reference CLI cannot produce them);
 *   2. targeted search for inputs whose output bytes exercise every branch of
 *      Python's bytes-repr escaping, each verified against the reference binary.
 */
import { spawnSync } from 'node:child_process';
import { AES } from '/output/lib/aes-core.mjs';
import { AESModeOfOperationECB } from '/output/lib/pyaes-ecb.mjs';
import { bytesRepr } from '/output/lib/pybytes.mjs';

const hex = (bytes) => Buffer.from(bytes).toString('hex');
const unhex = (s) => new Uint8Array(Buffer.from(s, 'hex'));

let failures = 0;
const expect = (label, got, want) => {
  if (got !== want) {
    failures++;
    console.log(`FAIL ${label}\n  got  ${got}\n  want ${want}`);
  }
};

// ---- 1. FIPS-197 appendix C known-answer vectors ----------------------------
const VECTORS = [
  ['C.1 AES-128', '000102030405060708090a0b0c0d0e0f', '00112233445566778899aabbccddeeff', '69c4e0d86a7b0430d8cdb78070b4c55a'],
  ['C.2 AES-192', '000102030405060708090a0b0c0d0e0f1011121314151617', '00112233445566778899aabbccddeeff', 'dda97ca4864cdfe06eaf70a0ec0d7191'],
  ['C.3 AES-256', '000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f', '00112233445566778899aabbccddeeff', '8ea2b7ca516745bfeafc49904b496089'],
  // FIPS-197 appendix B worked example.
  ['B AES-128', '2b7e151628aed2a6abf7158809cf4f3c', '3243f6a8885a308d313198a2e0370734', '3925841d02dc09fbdc118597196a0b32'],
  // SP 800-38A ECB-AES128 blocks 1-4.
  ['38A blk1', '2b7e151628aed2a6abf7158809cf4f3c', '6bc1bee22e409f96e93d7e117393172a', '3ad77bb40d7a3660a89ecaf32466ef97'],
  ['38A blk2', '2b7e151628aed2a6abf7158809cf4f3c', 'ae2d8a571e03ac9c9eb76fac45af8e51', 'f5d3d58503b9699de785895a96fdbaaf'],
  ['38A blk4', '2b7e151628aed2a6abf7158809cf4f3c', 'f69f2445df4f9b17ad2b417be66c3710', '7b0c785e27e8ad3f8223207104725dd4'],
  ['38A-256 b1', '603deb1015ca71be2b73aef0857d77811f352c073b6108d72d9810a30914dff4', '6bc1bee22e409f96e93d7e117393172a', 'f3eed1bdb5d2a03c064b5a7e3db181f8'],
];

for (const [label, key, plain, cipher] of VECTORS) {
  const aes = new AES(unhex(key));
  expect(`${label} encrypt`, hex(aes.encryptBlock(unhex(plain))), cipher);
  expect(`${label} decrypt`, hex(aes.decryptBlock(unhex(cipher))), plain);
}

// Round-trip fuzz over all three key sizes with fully random bytes.
for (const size of [16, 24, 32]) {
  for (let i = 0; i < 300; i++) {
    const key = new Uint8Array(size).map(() => Math.floor(Math.random() * 256));
    const block = new Uint8Array(16).map(() => Math.floor(Math.random() * 256));
    const aes = new AES(key);
    expect(`roundtrip-${size}`, hex(aes.decryptBlock(aes.encryptBlock(block))), hex(block));
  }
}
console.log(`vectors + roundtrips done (${failures} failures so far)`);

// ---- 2. repr escaping: find inputs hitting each branch, confirm vs binary ---
const printableKey = '0123456789abcdef';
const cipherFor = (data) => new AESModeOfOperationECB(Buffer.from(printableKey)).encrypt(Buffer.from(data));

const BRANCHES = {
  'both-quotes': (b) => b.includes(0x27) && b.includes(0x22),
  backslash: (b) => b.includes(0x5c),
  tab: (b) => b.includes(0x09),
  newline: (b) => b.includes(0x0a),
  carriage: (b) => b.includes(0x0d),
  del_7f: (b) => b.includes(0x7f),
  'single-quote-only': (b) => b.includes(0x27) && !b.includes(0x22),
  'double-quote-only': (b) => b.includes(0x22) && !b.includes(0x27),
};

const found = {};
const alphabet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
for (let attempt = 0; attempt < 400000 && Object.keys(found).length < Object.keys(BRANCHES).length; attempt++) {
  const data = Array.from({ length: 16 }, () => alphabet[Math.floor(Math.random() * alphabet.length)]).join('');
  const out = cipherFor(data);
  for (const [name, test] of Object.entries(BRANCHES)) {
    if (!found[name] && test(out)) found[name] = data;
  }
}

for (const [name, data] of Object.entries(found)) {
  const args = ['--key1', printableKey, '--key2', printableKey, '--data', data];
  const ref = spawnSync('/workspace/dataset/test15_executable', args, { encoding: 'binary' });
  const js = spawnSync('node', ['/output/test15.mjs', ...args], { encoding: 'binary' });
  expect(`repr ${name} (data=${data})`, js.stdout, ref.stdout);
  const mine = bytesRepr(cipherFor(data));
  expect(`repr ${name} first line`, mine, ref.stdout.split('\n')[0]);
}

const missing = Object.keys(BRANCHES).filter((k) => !(k in found));
console.log(`repr branches covered: ${Object.keys(found).length}/${Object.keys(BRANCHES).length}${missing.length ? ' missing: ' + missing.join(',') : ''}`);
for (const [name, data] of Object.entries(found)) console.log(`  ${name.padEnd(18)} ${bytesRepr(cipherFor(data))}`);

console.log(failures === 0 ? 'ALL CHECKS PASS' : `${failures} FAILURES`);
process.exit(failures === 0 ? 0 : 1);

