for (let i = 0; i < 10; i++) cases.push(['aes192', ['--key1', rand(24), '--key2', rand(24), '--data', rand(16)]]);
for (let i = 0; i < 10; i++) cases.push(['aes256', ['--key1', rand(32), '--key2', rand(32), '--data', rand(16)]]);
for (let i = 0; i < 6; i++) cases.push(['mixed-sizes', ['--key1', rand(16), '--key2', rand(32), '--data', rand(16)]]);
for (let i = 0; i < 6; i++) cases.push(['k1-192-k2-256', ['--key1', rand(24), '--key2', rand(32), '--data', rand(16)]]);

// Byte values that stress bytes-repr: high bytes, control chars, quotes.
for (let i = 0; i < 12; i++) cases.push(['low-ascii', ['--key1', rand(16, 32, 47), '--key2', rand(16, 32, 47), '--data', rand(16, 32, 47)]]);
cases.push(['quotes', ['--key1', '\'"\'"\'"\'"\'"\'"\'"\'"', '--key2', '""""""""\'\'\'\'\'\'\'\'', '--data', '\\\\\\\\\'\'\'\'""""\t\n\r\x0b']]);
cases.push(['tabs-newlines', ['--key1', 'a\tb\nc\rd\\efghijk', '--key2', '\t\t\t\t\n\n\n\n\r\r\r\r\\\\\\\\', '--data', '\t\n\r\\"\'abcdefghi']]);
cases.push(['identity-roundtrip', ['--key1', '0123456789abcdef', '--key2', '0123456789abcdef', '--data', '0123456789abcdef']]);
cases.push(['all-same-char', ['--key1', 'AAAAAAAAAAAAAAAA', '--key2', 'AAAAAAAAAAAAAAAA', '--data', 'AAAAAAAAAAAAAAAA']]);

// Multi-byte UTF-8: encode() decides the byte length, not the char count.
cases.push(['utf8-16-bytes', ['--key1', 'éeeeeeeeeeeeeee', '--key2', '0123456789abcdef', '--data', 'ééeeeeeeeeeeee']]);
cases.push(['utf8-emoji', ['--key1', '😀😀😀😀', '--key2', '😀😀😀😀', '--data', '😀😀😀😀']]);
cases.push(['utf8-cjk', ['--key1', '中文密钥测试abcd', '--key2', '0123456789abcdef', '--data', '中文数据中文abcd']]);
cases.push(['utf8-too-long', ['--key1', 'ééééééééééééééé', '--key2', '0123456789abcdef', '--data', '0123456789abcdef']]);

// Wrong lengths -> ValueError paths.
for (const n of [0, 1, 15, 17, 23, 25, 31, 33, 48]) {
  cases.push([`key1-len-${n}`, ['--key1', rand(n), '--key2', rand(16), '--data', rand(16)]]);
  cases.push([`key2-len-${n}`, ['--key1', rand(16), '--key2', rand(n), '--data', rand(16)]]);
  cases.push([`data-len-${n}`, ['--key1', rand(16), '--key2', rand(16), '--data', rand(n)]]);
}

// argparse surface.
const K = '0123456789abcdef';
cases.push(['no-args', []]);
cases.push(['help', ['-h']]);
cases.push(['help-long', ['--help']]);
cases.push(['help-with-others', ['--key1', K, '-h']]);
cases.push(['missing-data', ['--key1', K, '--key2', K]]);
cases.push(['missing-key2-data', ['--key1', K]]);
cases.push(['equals-form', [`--key1=${K}`, `--key2=${K}`, `--data=${K}`]]);
cases.push(['abbrev', ['--key1', K, '--key2', K, '--dat', K]]);
cases.push(['abbrev-min', ['--key1', K, '--key2', K, '--d', K]]);
cases.push(['abbrev-equals', [`--key1=${K}`, `--key2=${K}`, `--da=${K}`]]);
cases.push(['ambiguous-key', ['--key', K, '--key2', K, '--data', K]]);
cases.push(['ambiguous-k', ['--k', K, '--key2', K, '--data', K]]);
cases.push(['ambiguous-equals', [`--key=${K}`, '--key2', K, '--data', K]]);
cases.push(['unknown-opt', ['--key1', K, '--key2', K, '--data', K, '--foo', '1']]);
cases.push(['unknown-opt-only', ['--foo']]);
cases.push(['positional-extra', ['--key1', K, '--key2', K, '--data', K, 'extra']]);
cases.push(['dash-dash', ['--', '--key1', K, '--key2', K, '--data', K]]);
cases.push(['dash-dash-after', ['--key1', K, '--key2', K, '--data', K, '--']]);
cases.push(['dash-value', ['--key1', '-123456789abcdef', '--key2', K, '--data', K]]);
cases.push(['negative-number-value', ['--key1', K, '--key2', K, '--data', '-5']]);
cases.push(['negative-float-value', ['--key1', K, '--key2', K, '--data', '-5.5']]);
cases.push(['negative-number-equals', ['--key1', K, '--key2', K, `--data=-5`]]);
cases.push(['value-with-space-dash', ['--key1', K, '--key2', K, '--data', '-a bcdefghijklmn']]);
cases.push(['lone-dash-value', ['--key1', '-', '--key2', K, '--data', K]]);
cases.push(['empty-value', ['--key1', '', '--key2', K, '--data', K]]);
cases.push(['empty-equals', ['--key1=', '--key2', K, '--data', K]]);
cases.push(['missing-value-at-end', ['--key1', K, '--key2', K, '--data']]);
cases.push(['duplicate-last-wins', ['--key1', 'ffffffffffffffff', '--key1', K, '--key2', K, '--data', K]]);
cases.push(['duplicate-data', ['--key1', K, '--key2', K, '--data', 'AAAAAAAAAAAAAAAA', '--data', K]]);
cases.push(['out-of-order', ['--data', K, '--key2', K, '--key1', K]]);
cases.push(['equals-inside-value', ['--key1', `a=b456789abcdef1`, '--key2', K, '--data', K]]);
cases.push(['help-abbrev', ['--hel']]);
cases.push(['double-dash-only-first', ['--', '--', '--key1', K]]);
cases.push(['dash-dash-then-extra', ['--key1', K, '--key2', K, '--data', K, '--', 'extra']]);
cases.push(['dash-dash-twice-trailing', ['--key1', K, '--key2', K, '--data', K, '--', '--']]);
cases.push(['dash-dash-as-value', ['--key1', '--', '--key2', K, '--data', K]]);
cases.push(['dash-dash-mid', ['--key1', K, '--', '--key2', K, '--data', K]]);
cases.push(['dash-dash-then-h', ['--key1', K, '--key2', K, '--data', K, '--', '-h']]);
cases.push(['dash-dash-equals', ['--=x', '--key2', K, '--data', K]]);
cases.push(['triple-dash', ['---foo', '--key1', K, '--key2', K, '--data', K]]);
cases.push(['bare-dash-opt', ['-', '--key1', K, '--key2', K, '--data', K]]);
cases.push(['short-unknown', ['-x', '--key1', K, '--key2', K, '--data', K]]);
cases.push(['key1-eq-dash-value', ['--key1=-abcdefghijklmno', '--key2', K, '--data', K]]);
cases.push(['data-eq-empty-then-ok', ['--data=', '--key1', K, '--key2', K]]);

for (const [label, argv] of cases) check(label, argv);

console.log(`pass ${pass}/${cases.length}`);
for (const f of failures.slice(0, 12)) {
  console.log(`\nFAIL [${f.label}] argv=${JSON.stringify(f.argv)}`);
  console.log(`  ref: code=${f.ref.code} out=${JSON.stringify(f.ref.stdout)} err=${JSON.stringify(f.ref.stderr)}`);
  console.log(`  js : code=${f.js.code} out=${JSON.stringify(f.js.stdout)} err=${JSON.stringify(f.js.stderr)}`);
}
process.exit(failures.length === 0 ? 0 : 1);

