// Single-dash tokens: '=' does not split them, but a short option may carry an
// attached value. These also pin down which error wins when several are latent.
cases.push(['single-dash-eq-value', ['--key1', '-=<DD_x!#rw4y}xj', '--key2', K, '--data', K]]);
cases.push(['single-dash-eq-alone', ['-=x', '--key1', K, '--key2', K, '--data', K]]);
cases.push(['h-attached', ['-hxyz']]);
cases.push(['h-attached-eq', ['-h=x']]);
cases.push(['h-attached-eq-empty', ['-h=']]);
