cases.push(['help-eq-value', ['--help=x']]);
cases.push(['help-abbrev-eq-value', ['--hel=x']]);
cases.push(['h-as-value', ['--key1', '-hxyz', '--key2', K, '--data', K]]);
cases.push(['ambiguous-after-flag', ['--key1', '-h', '--key']]);
cases.push(['ambiguous-late', ['--key1', K, '--key2', K, '--data', K, '--key']]);
cases.push(['ambiguous-after-dashdash', ['--key1', '--', '--key']]);
cases.push(['ambiguous-after-unknown', ['--nope', '--key']]);
cases.push(['single-dash-long', ['-key1', K, '--key2', K, '--data', K]]);
cases.push(['eq-in-abbrev-value', ['--dat=a=b456789abcdef1', '--key1', K, '--key2', K]]);

for (const [label, argv] of cases) check(label, argv);

console.log(`pass ${pass}/${cases.length}`);
for (const f of failures.slice(0, 12)) {
  console.log(`\nFAIL [${f.label}] argv=${JSON.stringify(f.argv)}`);
  console.log(`  ref: code=${f.ref.code} out=${JSON.stringify(f.ref.stdout)} err=${JSON.stringify(f.ref.stderr)}`);
  console.log(`  js : code=${f.js.code} out=${JSON.stringify(f.js.stdout)} err=${JSON.stringify(f.js.stderr)}`);
}
process.exit(failures.length === 0 ? 0 : 1);
